    """Count unique words (case‑insensitive)."""
    cleaned = re.sub(r'[^a-z0-9]+', ' ', text.lower())
    words = cleaned.split()
    unique = []
    for w in words:
        if w not in unique:
            unique.append(w)
    return len(unique)
```
